    insertText: "CalculaPrecoProRata(${1:<pCriPrt>}, ${2:<pPreUni>}, ${3:<pIniVig>}, ${4:<pFimVig>}, ${5:<pCptFat>}, ${6:<pDatAux>}, ${7:<pCriFtc>}, ${8:<pProRat>});",
    detail: "ERP · CalculaPrecoProRata (Numero pCriPrt,Numero pPreUni,Numero pIniVig, Numero pFimVig,Numero pCptFat,Numero pDatAux,Numero pCriFtc,Alfa pProRat)",
    documentation: "**CalculaPrecoProRata**\n`Funcao CalculaPrecoProRata (Numero pCriPrt,Numero pPreUni,Numero pIniVig, Numero pFimVig,Numero pCptFat,Numero pDatAux,Numero pCriFtc,Alfa pProRat);`\n\nCalcular o preço unitário do contrato com base no critério pró-rata por competência (padrão do sistema) ou por período (através do identificador de regras VEN-160PRORA01).\n\n**Parâmetros**\n- `<pCriPrt>` (Numero) — Critério para cálculo pró-rata do contrato de venda.\n- `<pPreUni>` (Numero) — Preço unitário do produto ou serviço.\n- `<pIniVig>` (Numero) — Data de início da vigência do item do contrato.\n- `<pFimVig>` (Numero) — Data final da vigência do item do contrato.\n- `<pCptFat>` (Numero) — Competência que está sendo faturada.\n- `<pDatAux>` (Numero) — Competência que está sendo faturada.\n- `<pCriFtc>` (Numero) — Critério para faturamento do contrato de venda.\n- `<pProRat>` (Alfa) — Indicativo se deve ser feito o cálculo pró-rata para o item do contrato.\n\n_Sistema: ERP_\n_Fonte: [doc Senior](https://documentacao.senior.com.br/gestaoempresarialerp/5.10.4/regra_funcoes/calculaprecoprorata.htm)_",
    kind: "function",
    isSnippet: true,
    system: "ERP",
    params: [{"name":"pCriPrt","tipo":"Numero","description":"Critério para cálculo pró-rata do contrato de venda."},{"name":"pPreUni","tipo":"Numero","description":"Preço unitário do produto ou serviço."},{"name":"pIniVig","tipo":"Numero","description":"Data de início da vigência do item do contrato."},{"name":"pFimVig","tipo":"Numero","description":"Data final da vigência do item do contrato."},{"name":"pCptFat","tipo":"Numero","description":"Competência que está sendo faturada."},{"name":"pDatAux","tipo":"Numero","description":"Competência que está sendo faturada."},{"name":"pCriFtc","tipo":"Numero","description":"Critério para faturamento do contrato de venda."},{"name":"pProRat","tipo":"Alfa","description":"Indicativo se deve ser feito o cálculo pró-rata para o item do contrato."}],
