    label: "CarregaConvIcms96",
    insertText: "CarregaConvIcms96(${1:<pCodEmp>}, ${2:<pCodFil>}, ${3:<pDatIni>}, ${4:<pDatFim>}, ${5:<pSigUfs>}, ${6:<pTipLay>}, ${7:<pFinArq>}, ${8:<Versao>}, ${9:<pEntSai>}, ${10:<pImpCom>}, ${11:<pApresent>});",
    detail: "ERP · CarregaConvIcms96(Numero pCodEmp, Alfa pCodFil, Numero pDatIni, Numero pDatFim, Alfa pSigUfs, Numero pTipLay, Numero pFinArq, Numero Versao, Alfa pEntSai, Alfa pImpCom, Numero pApresent)",
    documentation: "**CarregaConvIcms96**\n`Funcao CarregaConvIcms96(Numero pCodEmp, Alfa pCodFil, Numero pDatIni, Numero pDatFim, Alfa pSigUfs, Numero pTipLay, Numero pFinArq, Numero Versao, Alfa pEntSai, Alfa pImpCom, Numero pApresent);`\n\nEsta função abre uma das diversas query's usadas para carregar informações para a exportação do Convênio ICMS 96/97 e posteriores.\n\n**Parâmetros**\n- `<pCodEmp>` (Numero) — Variável que recebe o código da empresa (chave das tabelas).\n- `<pCodFil>` (Alfa) — Variável que recebe a abrangência de filiais (chave das tabelas).\n- `<pDatIni>` (Numero) — Variável que recebe a data inicial do movimento.\n- `<pDatFim>` (Numero) — Variável que recebe a data final do movimento.\n- `<pSigUfs>` (Alfa) — Variável que recebe a sigla do estado da filial.\n- `<pTipLay>` (Numero) — Variável que recebe o tipo do registro do Convênio ICMS 96/97 e posteriores que se deseja carregar.\n- `<pFinArq>` (Numero) — Variável que recebe a finalidade do arquivo magnético.\n- `<Versao>` (Numero) — Versão do convênio do qual se deseja carregar os dados (0 = Convênio ICMS 96/97 / 1 = Convênio ICMS 31/99).\n- `<pEntSai>` (Alfa) — Variável que recebe o tipo de movimento que se deseja exportar (E = Entradas / S = Saídas / A = Ambos).\n- `<pImpCom>` (Alfa) — Variável que recebe a origem dos dados a ser exportados (I = Impostos / C = Comercial).\n- `<pApresent>` (Numero) — Variável que recebe a apresentação do arquivo magnético (1 = Normal / 2 = Retificação Total / 3 = Retificação Aditiva / 4 = Retificação Corretiva / 5 = Desfazimento).\n\n_Sistema: ERP_\n_Fonte: [doc Senior](https://documentacao.senior.com.br/gestaoempresarialerp/5.10.3/regra_funcoes/carregaconvicms96.htm)_",
    kind: "function",
    isSnippet: true,
    system: "ERP",
    params: [{"name":"pCodEmp","tipo":"Numero","description":"Variável que recebe o código da empresa (chave das tabelas)."},{"name":"pCodFil","tipo":"Alfa","description":"Variável que recebe a abrangência de filiais (chave das tabelas)."},{"name":"pDatIni","tipo":"Numero","description":"Variável que recebe a data inicial do movimento."},{"name":"pDatFim","tipo":"Numero","description":"Variável que recebe a data final do movimento."},{"name":"pSigUfs","tipo":"Alfa","description":"Variável que recebe a sigla do estado da filial."},{"name":"pTipLay","tipo":"Numero","description":"Variável que recebe o tipo do registro do Convênio ICMS 96/97 e posteriores que se deseja carregar."},{"name":"pFinArq","tipo":"Numero","description":"Variável que recebe a finalidade do arquivo magnético."},{"name":"Versao","tipo":"Numero","description":"Versão do convênio do qual se deseja carregar os dados (0 = Convênio ICMS 96/97 / 1 = Convênio ICMS 31/99)."},{"name":"pEntSai","tipo":"Alfa","description":"Variável que recebe o tipo de movimento que se deseja exportar (E = Entradas / S = Saídas / A = Ambos)."},{"name":"pImpCom","tipo":"Alfa","description":"Variável que recebe a origem dos dados a ser exportados (I = Impostos / C = Comercial)."},{"name":"pApresent","tipo":"Numero","description":"Variável que recebe a apresentação do arquivo magnético (1 = Normal / 2 = Retificação Total / 3 = Retificação Aditiva / 4 = Retificação Corretiva / 5 = Desfazimento)."}],
