    insertText: "CarregaSaldoDeposito(${1:<pCodEmp>}, ${2:<pCodFil>}, ${3:<pDatSal>}, ${4:<pCodOri>}, ${5:<pCodFam>}, ${6:<pCodPro>}, ${7:<pCodDer>}, ${8:<pCodDep>}, ${9:<pCodAge>});",
    detail: "ERP · CarregaSaldoDeposito(Numero pCodEmp, Numero pCodFil,Numero pDatSal,Alfa pCodOri,Alfa pCodFam,Alfa pCodPro, Alfa pCodDer,Alfa pCodDep,Alfa pCodAge)",
    documentation: "**CarregaSaldoDeposito**\n`Funcao CarregaSaldoDeposito(Numero pCodEmp, Numero pCodFil,Numero pDatSal,Alfa pCodOri,Alfa pCodFam,Alfa pCodPro, Alfa pCodDer,Alfa pCodDep,Alfa pCodAge);`\n\nEsta função carrega os saldos de estoque por depósito para uma lista de dados para posterior leitura através da função LeSaldoDeposito;\n\n**Parâmetros**\n- `<pCodEmp>` (Numero) — Código da empresa, obrigatório.\n- `<pCodFil>` (Numero) — Código da filial, se for igual a zero traz todas as filiais.\n- `<pDatSal>` (Numero) — Data do saldo desejado, obrigatório.\n- `<pCodOri>` (Alfa) — Código da origem, filtro.\n- `<pCodFam>` (Alfa) — Código da família, filtro.\n- `<pCodPro>` (Alfa) — Código do produto, filtro.\n- `<pCodDer>` (Alfa) — Código da derivação, filtro.\n- `<pCodDep>` (Alfa) — Código do depósito, filtro.\n- `<pCodAge>` (Alfa) — Código do agrupamento de estoque, filtro.\n\n_Sistema: ERP_\n_Fonte: [doc Senior](https://documentacao.senior.com.br/gestaoempresarialerp/5.10.3/regra_funcoes/carregasaldodeposito.htm)_",
    kind: "function",
    isSnippet: true,
    system: "ERP",
    params: [{"name":"pCodEmp","tipo":"Numero","description":"Código da empresa, obrigatório."},{"name":"pCodFil","tipo":"Numero","description":"Código da filial, se for igual a zero traz todas as filiais."},{"name":"pDatSal","tipo":"Numero","description":"Data do saldo desejado, obrigatório."},{"name":"pCodOri","tipo":"Alfa","description":"Código da origem, filtro."},{"name":"pCodFam","tipo":"Alfa","description":"Código da família, filtro."},{"name":"pCodPro","tipo":"Alfa","description":"Código do produto, filtro."},{"name":"pCodDer","tipo":"Alfa","description":"Código da derivação, filtro."},{"name":"pCodDep","tipo":"Alfa","description":"Código do depósito, filtro."},{"name":"pCodAge","tipo":"Alfa","description":"Código do agrupamento de estoque, filtro."}],
