    insertText: "EntradaValor(${1:<PCaption>}, ${2:<pDesTit>}, ${3:<pTipDad>}, ${4:<pMasc>}, ${5:<pIniAlfa>}, ${6:<pIniNum>}, ${7:<pRetAlfa>}, ${8:<pRetNum>}, ${9:<pTipSai>});",
    detail: "ERP · EntradaValor(alfa PCaption,alfa pDesTit,Numero pTipDad,Alfa pMasc,alfa pIniAlfa,Numero pIniNum,Alfa end pRetAlfa,Numero end pRetNum,Numero end pTipSai)",
    documentation: "**EntradaValor**\n`EntradaValor(alfa PCaption,alfa pDesTit,Numero pTipDad,Alfa pMasc,alfa pIniAlfa,Numero pIniNum,Alfa end pRetAlfa,Numero end pRetNum,Numero end pTipSai);`\n\nFunção utilizada para entrada de valores nas regras.\n\n**Parâmetros**\n- `<PCaption>` (Alfa) — Valor ou variável que indicará o nome da tela.\n- `<pDesTit>` (Alfa) — Valor ou variável que indicará o nome da descrição do título do campo de entrada.\n- `<pTipDad>` (Numero) — Valor ou variável que indicará o tipo do dado para o campo de entrad;. (1=Números inteiros, 2=Números com casas decimais, 3=Data, 4=Hora, 5=Alfa e 6=Senha).\n- `<pMasc>` (Alfa) — Valor ou variável que indicará a mascara para ser aplicada no campo de entrada.\n- `<pIniAlfa>` (Alfa) — Valor ou variável que indicará o valor inicial alfanumérico para o campo de entrada.\n- `<pIniNum>` (Numero) — Valor ou variável que indicará o valor inicial numérico para o campo de entrada. Observação: esse parâmetro possui um limite, onde o valor máximo suportado pelo sistema é de 2.147.483.647.\n- `<pRetAlfa>` (Alfa) — Variável que receberá o retorno informado no campo de entrada.\n- `<pRetNum>` (Numero) — Variável que receberá o retorno informado no campo de entrada.\n- `<pTipSai>` (Numero) — Variável que receberá o tipo que o usuário saiu da tela; (1-OK;0-Só fechou a form).\n\n_Sistema: ERP_\n_Fonte: [doc Senior](https://documentacao.senior.com.br/gestaoempresarialerp/5.10.4/regra_funcoes/entradavalor.htm)_",
    kind: "function",
    isSnippet: true,
    system: "ERP",
    params: [{"name":"PCaption","tipo":"Alfa","description":"Valor ou variável que indicará o nome da tela."},{"name":"pDesTit","tipo":"Alfa","description":"Valor ou variável que indicará o nome da descrição do título do campo de entrada."},{"name":"pTipDad","tipo":"Numero","description":"Valor ou variável que indicará o tipo do dado para o campo de entrad;. (1=Números inteiros, 2=Números com casas decimais, 3=Data, 4=Hora, 5=Alfa e 6=Senha)."},{"name":"pMasc","tipo":"Alfa","description":"Valor ou variável que indicará a mascara para ser aplicada no campo de entrada."},{"name":"pIniAlfa","tipo":"Alfa","description":"Valor ou variável que indicará o valor inicial alfanumérico para o campo de entrada."},{"name":"pIniNum","tipo":"Numero","description":"Valor ou variável que indicará o valor inicial numérico para o campo de entrada. Observação: esse parâmetro possui um limite, onde o valor máximo suportado pelo sistema é de 2.147.483.647."},{"name":"pRetAlfa","tipo":"Alfa","description":"Variável que receberá o retorno informado no campo de entrada."},{"name":"pRetNum","tipo":"Numero","description":"Variável que receberá o retorno informado no campo de entrada."},{"name":"pTipSai","tipo":"Numero","description":"Variável que receberá o tipo que o usuário saiu da tela; (1-OK;0-Só fechou a form)."}],
