    params: [{"name":"aCodigoSistema","tipo":"Numero","description":"Variável do código de sistema integrado (tela F000SIS - Cadastros / Integrações / Cadastro de Sistemas Integrados)."},{"name":"aTipoInformacao","tipo":"Numero","description":"Variável do tipo de informação (ver na tabela abaixo). A variável deve ser preenchida com o conteúdo da coluna IdeInt que se quer exportar."},{"name":"aChave","tipo":"Alfa","description":"Variável referente a chave do registro que será gerado pendência, conforme tabela abaixo. Os códigos devem ser separados pelo caracter \";\"."},{"name":"aMsgRetorno","tipo":"Alfa","description":"Em caso de problemas na execução da função, esta mensagem será retornada por esta variável. Caso a execução seja bem sucedida, a variável não retornará nenhum conteúdo."}],
