    params: [{"name":"aInscricaoEstadual","tipo":"Alfa","description":"Variável que recebe a inscrição estadual. Se desejar, preencha com caracteres especiais. Por exemplo: \"252.812.441\""},{"name":"aSiglaUF","tipo":"Alfa","description":"Variável que recebe a sigla do estado."},{"name":"aResult","tipo":"Alfa","description":"Indicador da validade da inscrição estadual. Caso a inscrição seja válida a variável retornará SIM, caso contrário, retornará NAO."}],
