    params: [{"name":"pCtaRed","tipo":"Numero","description":"Variável que recebe o número da conta contábil que deseja-se buscar o saldo contábil."},{"name":"pMesIni","tipo":"Numero","description":"Variável que recebe o mês inicial referente ao período utilizado para carregar o saldo das contas."},{"name":"pMesSal","tipo":"Numero","description":"Variável que recebe o mês inicial referente ao período que está sendo utilizado para retornar o saldo nas variáveis."},{"name":"pSalM01","tipo":"Alfa","description":"Variável que retorna o saldo referente ao primeiro mês do período informado."},{"name":"pSalM02","tipo":"Numero","description":"Variável que retorna o saldo referente ao segundo mês do período informado."},{"name":"pSalM03","tipo":"Numero","description":"Variável que retorna o saldo referente ao terceiro mês do período informado."},{"name":"pSalM04","tipo":"Numero","description":"Variável que retorna o saldo referente ao quarto mês do período informado."},{"name":"pSalM05","tipo":"Numero","description":"Variável que retorna o saldo referente ao quinto mês do período informado."},{"name":"pSalM06","tipo":"Numero","description":"Variável que retorna o saldo referente ao sexto mês do período informado."}],
